package auth

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"
)

// PostgreSQL SQLSTATE codes and the constraint names generated by the init
// migration. Matching on ConstraintName (not on error text) is what keeps the
// mapping stable across locales and Postgres versions.
const (
	sqlStateUniqueViolation    = "23505"
	constraintUsersUsernameKey = "users_username_key"
	constraintUsersEmailKey    = "users_email_key"
)

type PostgresUserRepository struct {
	pool *pgxpool.Pool
}

func NewUserRepository(pool *pgxpool.Pool) *PostgresUserRepository {
	return &PostgresUserRepository{pool: pool}
}

// CreateUser inserts a new user and populates the columns the database
// generates (id, created_at, updated_at) back onto the supplied model.
func (r *PostgresUserRepository) CreateUser(ctx context.Context, user *User) error {
	const query = `
		INSERT INTO users (username, email, password_hash, role, is_active)
		VALUES ($1, $2, $3, $4, $5)
		RETURNING id, created_at, updated_at
	`

	err := r.pool.QueryRow(ctx, query,
		user.Username,
		user.Email,
		user.PasswordHash,
		user.Role,
		user.IsActive,
	).Scan(&user.ID, &user.CreatedAt, &user.UpdatedAt)
	if err != nil {
		return mapCreateUserError(err)
	}

	return nil
}

// userColumns is the single source of truth for the column order that scanUser
// expects. Both read paths share it so a new column cannot silently desync the
// SELECT list from the Scan targets.
const userColumns = `id, username, email, password_hash, role, is_active,
		       email_verified, failed_logins, locked_until, last_login_at,
		       created_at, updated_at`

// GetUserByUsername returns the user with the given username by exact match.
// It returns ErrUserNotFound when no row matches.
func (r *PostgresUserRepository) GetUserByUsername(ctx context.Context, username string) (*User, error) {
	const query = `
		SELECT ` + userColumns + `
		FROM users
		WHERE username = $1
	`

	user, err := scanUser(r.pool.QueryRow(ctx, query, username))
	if err != nil {
		return nil, err
	}

	return user, nil
}

// GetUserByID returns the user with the given primary key. Refreshing an access
// token re-reads the user this way so a deactivated account cannot keep minting
// tokens from a refresh token issued before the deactivation.
func (r *PostgresUserRepository) GetUserByID(ctx context.Context, id int64) (*User, error) {
	const query = `
		SELECT ` + userColumns + `
		FROM users
		WHERE id = $1
	`

	user, err := scanUser(r.pool.QueryRow(ctx, query, id))
	if err != nil {
		return nil, err
	}

	return user, nil
}

// RecordFailedLogin advances the brute-force throttle for one user in a single
// statement, so concurrent attempts cannot lose increments through a
// read-modify-write race. Policy (the threshold and lock duration) is supplied
// by the service; this method only persists the outcome.
//
// Three rules live in the CTE:
//   - An expired lock is treated as a fresh counter. Otherwise a user who waited
//     out a lockout would be re-locked by a single typo.
//   - Reaching maxAttempts locks the account and resets failed_logins to 0, so
//     the counter and the lock can never disagree (the lock is the state, not
//     the count).
//   - An already-active lock is left exactly as it is. This closes a real race:
//     two failed attempts can both pass the service's pre-check as unlocked, and
//     without this rule the second write would wipe the lock the first one just
//     set.
//
// now() and the interval are evaluated by PostgreSQL so lock expiry does not
// depend on the application's clock.
func (r *PostgresUserRepository) RecordFailedLogin(ctx context.Context, userID int64, maxAttempts int16, lockDuration time.Duration) error {
	const query = `
		WITH current AS (
			SELECT id,
			       locked_until,
			       locked_until IS NOT NULL AND locked_until > now() AS has_active_lock,
			       CASE WHEN locked_until IS NOT NULL AND locked_until <= now()
			            THEN 0 ELSE failed_logins END AS base
			FROM users
			WHERE id = $1
		)
		UPDATE users u
		SET failed_logins = CASE
		        WHEN c.has_active_lock THEN u.failed_logins
		        WHEN c.base + 1 >= $2 THEN 0
		        ELSE c.base + 1 END,
		    locked_until = CASE
		        WHEN c.has_active_lock THEN c.locked_until
		        WHEN c.base + 1 >= $2 THEN now() + make_interval(secs => $3)
		        ELSE NULL END,
		    updated_at = now()
		FROM current c
		WHERE u.id = c.id
	`

	if _, err := r.pool.Exec(ctx, query, userID, maxAttempts, lockDuration.Seconds()); err != nil {
		return fmt.Errorf("record failed login: %w", err)
	}

	return nil
}

// RecordSuccessfulLogin clears the throttle state and stamps last_login_at. The
// lockout counter is reset here rather than in RecordFailedLogin so a successful
// login always starts the next window from zero.
func (r *PostgresUserRepository) RecordSuccessfulLogin(ctx context.Context, userID int64) error {
	const query = `
		UPDATE users
		SET failed_logins = 0,
		    locked_until  = NULL,
		    last_login_at = now(),
		    updated_at    = now()
		WHERE id = $1
	`

	if _, err := r.pool.Exec(ctx, query, userID); err != nil {
		return fmt.Errorf("record successful login: %w", err)
	}

	return nil
}

// scanUser scans one row selected in userColumns order, translating pgx's
// no-rows sentinel into ErrUserNotFound for every read path.
func scanUser(row pgx.Row) (*User, error) {
	var user User
	err := row.Scan(
		&user.ID,
		&user.Username,
		&user.Email,
		&user.PasswordHash,
		&user.Role,
		&user.IsActive,
		&user.EmailVerified,
		&user.FailedLogins,
		&user.LockedUntil,
		&user.LastLoginAt,
		&user.CreatedAt,
		&user.UpdatedAt,
	)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return nil, ErrUserNotFound
		}
		return nil, fmt.Errorf("scan user: %w", err)
	}

	return &user, nil
}

// mapCreateUserError translates a unique violation on the username or email
// column into the matching domain error. Any other failure is wrapped so the
// caller keeps the original cause via errors.Is/errors.As.
func mapCreateUserError(err error) error {
	var pgErr *pgconn.PgError
	if errors.As(err, &pgErr) && pgErr.Code == sqlStateUniqueViolation {
		switch pgErr.ConstraintName {
		case constraintUsersUsernameKey:
			return fmt.Errorf("create user: %w", ErrUsernameTaken)
		case constraintUsersEmailKey:
			return fmt.Errorf("create user: %w", ErrEmailTaken)
		default:
			// Unmapped unique violation: keep it loud instead of guessing which
			// field collided, so a new constraint is never misreported to the
			// client as a taken username/email.
			return fmt.Errorf("create user: unhandled unique violation on constraint %q: %w", pgErr.ConstraintName, err)
		}
	}

	return fmt.Errorf("create user: %w", err)
}
